{
  "packet_id": "H6-T01-1",
  "claim_id": "C036",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C036.component",
    "value": "Historical weeks may provide context only when their coverage is comparable.",
    "scope": "Coverage comparability is a necessary condition alongside comparable definitions; the required degree of coverage comparability is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P019 explicitly supplies both comparability requirements and restricts historical weeks to contextual use."
    }
  },
  "signal_basis": {
    "component_id": "C036.signal_basis",
    "value": "Historical bookings are linked to turnaround records with missing values retained, and temporal observations are presented with booking denominators and missing-record counts. Historical context requires comparable definitions and coverage.",
    "scope": "The preceding six weeks inform interpretation of the investigation sequence only under the stated comparability restrictions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the historical record linkage, visibility of observation coverage, and limits on contextual use."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C036.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its explicit bounds without an unresolved empirical relation."
    }
  },
  "rationale": "Comparable coverage is a warranted restriction on using historical weeks to interpret a temporal sequence: differences in what is recorded can produce apparent differences across weeks. The claim states a necessary condition for contextual use, without treating coverage comparability as sufficient or claiming that it has already been established.",
  "uncertainty": "The mapping does not specify how much coverage comparability is required. This limits application precision but does not undermine the stated restriction.",
  "anomalies": []
}
